BEGIN; DO $$ DECLARE actor uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); wh uuid:=gen_random_uuid(); customer uuid:=gen_random_uuid(); args jsonb; followup jsonb; result jsonb; proposal jsonb; reviewer uuid; BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(actor,'integral-edit-test-'||actor||'@example.invalid','{}',now()); INSERT INTO public.user_roles(user_id,role) VALUES(actor,'vendedor') ON CONFLICT DO NOTHING; SELECT user_id INTO reviewer FROM public.user_roles WHERE role='superadmin' LIMIT 1; PERFORM set_config('request.jwt.claim.sub',reviewer::text,true); INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Controlled policy test',true,true); INSERT INTO public.inventory_items(id,product_id,name,unit,currency,cost,price,quantity,reserved,is_active,is_demo) VALUES(item,prod,'Controlled item','UN','BRL',10,100,10,0,true,true); INSERT INTO public.warehouses(id,name,city,state,is_active) VALUES(wh,'Controlled warehouse','Controlled city','SP',true); INSERT INTO public.warehouse_inventory(warehouse_id,item_id,quantity,reserved) VALUES(wh,item,9,0); INSERT INTO public.customers(id,name,created_by,is_demo) VALUES(customer,'Controlled identified customer',actor,true); INSERT INTO public.orders(id,number,seller_id,product_id,warehouse_id,currency,total,amount_paid,amount_receivable,status,kind,stock_state,workflow_stage,order_date,exchange_rates_snapshot,exchange_rate_locked_at,is_demo,variable_cost) VALUES(oid,-2147480002,actor,prod,wh,'BRL',100,0,100,'faturado','venda','baixado','pedido_feito',current_date,jsonb_build_object('base','BRL','BRL',1,'USD',0.2,'PYG',1400),now(),true,37); INSERT INTO public.order_items(order_id,item_id,description,unit,quantity,unit_price,discount,total) VALUES(oid,item,'Controlled item','UN',1,100,0,100); args:=jsonb_build_object('p_previous_order_id',oid,'p_customer_id',customer,'p_product_id',prod,'p_currency','BRL','p_discount',0,'p_shipping_cost',0,'p_shipping_percentage',null,'p_notes','Controlled edit','p_whatsapp',null,'p_items',jsonb_build_array(jsonb_build_object('item_id',item,'description','Controlled item','unit','UN','quantity',2,'unit_price',100,'discount',0)),'p_warehouse_id',wh,'p_shipping_address','Test address','p_shipping_city','Test city','p_shipping_state','SP','p_delivery_deadline',null,'p_carrier','Controlled carrier','p_tracking_code','CONTROLLED123'); followup:=jsonb_build_object('delivery_recipient_name','Controlled','delivery_recipient_document','','shipping_cep','','variable_cost',0,'seller_id',actor,'order_date',current_date,'delivery_deadline',null,'delivered_at',null,'shipping_country','Brasil','shipping_address_number','1'); INSERT INTO public.product_users(user_id,product_id) VALUES(actor,prod); PERFORM set_config('request.jwt.claim.sub',actor::text,true); followup:=followup-'variable_cost'; proposal:=public.integral_submit_order_edit(args,followup,null,'Controlled quantity update',gen_random_uuid());
 IF NOT coalesce((proposal->>'pending_approval')::boolean,false) OR proposal->>'request_id' IS NULL THEN RAISE EXCEPTION 'Legacy edit skipped approval'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=oid AND customer_id IS NULL AND superseded_at IS NULL AND total=100) THEN RAISE EXCEPTION 'Proposal changed active order'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.order_change_requests WHERE id=(proposal->>'request_id')::uuid AND status='pending' AND proposed_args->>'p_customer_id'=customer::text) THEN RAISE EXCEPTION 'Customer change missing from queue'; END IF;
 PERFORM set_config('request.jwt.claim.sub',reviewer::text,true);
 result:=public.integral_review_order_change((proposal->>'request_id')::uuid,true,'Controlled independent approval'); IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=(result->>'id')::uuid AND customer_id=customer AND carrier='Controlled carrier' AND tracking_code='CONTROLLED123' AND variable_cost=37) THEN RAISE EXCEPTION 'Counter sale conversion or logistics lost'; END IF; IF public.division_order_context((result->>'id')::uuid)->'order' ? 'gross_margin' THEN RAISE EXCEPTION 'Divisional context leaked cost'; END IF; IF result->>'id' IS NULL OR (SELECT count(*) FROM public.orders WHERE root_order_id=oid AND superseded_at IS NULL)<>1 THEN RAISE EXCEPTION 'Order revision test failed'; END IF; END $$; ROLLBACK;

